        statements.saveAndFlush(new Statement(sheetId, personId, today, today, dueTotal, counted,
                nextSeq(sheetId, personId)));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
